class IrisRequest(BaseModel):
    sepal_length: float
    sepal_width: float
    petal_length: float
    petal_width: float

@app.post("/predict")
def predict(req: IrisRequest):
    features = [[req.sepal_length, req.sepal_width,
                 req.petal_length, req.petal_width]]
    return {"prediction": int(model.predict(features)[0])}
